{
  "a_sentences": [
    {
      "a_text": "La juridiction cantonale a retenu que l'incapacité de travail invalidante remontait au mois de juin 2018, selon l'évaluation des organes de l'assurance-invalidité.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Le Tribunal fédéral examine si un lien de connexité temporelle et matérielle existe entre l'incapacité de travail survenue durant l'affiliation à la CIEPP et l'invalidité ultérieure ayant conduit à l'octroi d'une rente entière de l'assurance-invalidité à compter du 1er septembre 2020, au regard de l'art. 23 let. a LPP.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Le Tribunal fédéral rappelle que l'institution de prévoyance est liée par l'évaluation de l'invalidité de l'assurance-invalidité, sous réserve d'une estimation insoutenable, et que la connexité temporelle exige une interruption de la capacité de travail de plus de trois mois.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "La juridiction cantonale a nié le lien de connexité temporelle, estimant que la personne assurée avait recouvré une capacité de travail de plus de 80 % dans une activité adaptée de février 2017 à juin 2018, sans l'exploiter pour des motifs personnels.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Le Tribunal fédéral rejette l'argument selon lequel l'absence de mise en valeur de la capacité de travail résiduelle constituerait une violation de l'art. 23 LPP, car la rupture du lien de connexité temporelle est confirmée.",
      "b_propositions": ["P5"]
    }
  ]
}
